using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Security.Cryptography;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

public static class EffectSourcePresentationValidation
{
    public static bool Running{get;private set;}
    public static string Output{get;private set;}
    const string Base=".tools/effect-source-1006/ui";
    [Serializable] sealed class Meta{public string folder,status,runtimeHash;}
    static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    static string Hash(string p){using var h=SHA256.Create();return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(p))).Replace("-","").ToLowerInvariant();}
    static Transform Root=>GameObject.Find("Canvas").transform;
    static IEnumerator Frame(){yield return new WaitForSecondsRealtime(.2f);yield return new WaitForEndOfFrame();Canvas.ForceUpdateCanvases();}
    public static void Run(){Check(Application.isPlaying&&!Running,"Play required/already running");Running=true;Output=Base+"/"+DateTime.UtcNow.ToString("yyyyMMddTHHmmssfffffffZ");Directory.CreateDirectory(Output+"/inputs");File.WriteAllText(Base+"/latest.txt",Output);File.WriteAllText(Output+"/result.txt","RUNNING");File.WriteAllText(Output+"/producer-hashes.tsv",string.Join("\n",new[]{"Assets/Scripts/Editor/EffectSourcePresentationValidation.cs","Assets/Scripts/UI/ForgeBattlefieldController.AbilityFace.cs","Assets/Scripts/UI/ForgeBattlefieldController.TokenArt.cs","Assets/Scripts/UI/ForgeBattlefieldController.Stack.cs","Assets/Scripts/UI/ForgeBattlefieldController.Integrated.cs","Assets/Scripts/Networking/ForgeWire.cs"}.Select(p=>p+"\t"+Hash(p)))+"\n");var go=new GameObject("EffectSourceValidation");go.AddComponent<Host>().StartCoroutine(Guard(Exercise(),go));}
    sealed class Host:MonoBehaviour{}
    static IEnumerator Guard(IEnumerator e,GameObject go){Exception error=null;while(true){bool more=false;object current=null;try{more=e.MoveNext();if(more)current=e.Current;}catch(Exception ex){error=ex;break;}if(!more)break;if(current is IEnumerator nested){yield return Nested(nested,ex=>error=ex);if(error!=null)break;}else yield return current;}try{(e as IDisposable)?.Dispose();}catch(Exception ex){error??=ex;}File.WriteAllText(Output+"/result.txt",error==null?"PASS: actual Embolden replacement-order inputs, generated effect IDs separate from public artwork source, three locales exact art/localized generic title/prevention values; actual native order IDs by raycast, duplicate/read-only guards, view/return font stability; unknown effect text/name and face-down artwork adapters preserved. No new rule or network proof.":"FAIL\n"+error);Running=false;UnityEngine.Object.Destroy(go);}
    static IEnumerator Nested(IEnumerator e,Action<Exception> fail){while(true){bool more=false;object current=null;try{more=e.MoveNext();if(more)current=e.Current;}catch(Exception ex){fail(ex);break;}if(!more)break;if(current is IEnumerator child)yield return Nested(child,fail);else yield return current;}}
    static void Click(Button b){var rect=(RectTransform)b.transform;var p=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,rect.TransformPoint(rect.rect.center)),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(p,hits);Check(hits.Count>0&&hits[0].gameObject.GetComponentInParent<Button>()==b,"Order click blocked");ExecuteEvents.ExecuteHierarchy(hits[0].gameObject,p,ExecuteEvents.pointerClickHandler);}
    static IEnumerator Exercise(){
        var ui=UnityEngine.Object.FindFirstObjectByType<ForgeBattlefieldController>()??new GameObject("EffectSourceBattlefield").AddComponent<ForgeBattlefieldController>();bool enabled=ui.enabled;ui.enabled=false;var module=EventSystem.current.currentInputModule;bool active=module!=null&&module.enabled;if(module!=null)module.enabled=false;string locale=GamePreferences.Language;var notices=UnityEngine.Object.FindObjectsByType<ForgeBattlefieldMigrationNotice>(FindObjectsSortMode.None).Select(n=>(n,n.enabled)).ToArray();foreach(var n in notices)n.n.enabled=false;
        try{
            var meta=JsonUtility.FromJson<Meta>(File.ReadAllText(".tools/effect-source-1006/native/shield-division-result.json"));Check(meta.status=="PASS"&&meta.runtimeHash==JsonUtility.FromJson<Meta>(File.ReadAllText("ForgeRuntime/runtime.json")).runtimeHash,"Native proof stale");string path=Directory.GetFiles(meta.folder,"replacement-*.json").Where(p=>!p.EndsWith("-other.json")).OrderBy(p=>int.Parse(Path.GetFileNameWithoutExtension(p).Split('-').Last())).First(p=>JsonUtility.FromJson<ForgeSeatView>(File.ReadAllText(p)).request.options.Count(o=>o.ability!=null)==2);File.Copy(path,Output+"/inputs/order.json",true);File.AppendAllText(Output+"/input-hashes.tsv",path+"\t"+Hash(path)+"\n");
            foreach(string lang in new[]{"zh-CN","en-US","ja-JP"}){
                int revision=GamePreferences.Revision;bool change=GamePreferences.Language!=lang;GamePreferences.SetLanguage(lang);float until=Time.realtimeSinceStartup+20;while((!GamePreferences.Ready||change&&revision==GamePreferences.Revision)&&Time.realtimeSinceStartup<until)yield return null;Check(GamePreferences.Ready,"Language unavailable");yield return Frame();
                foreach(bool acting in new[]{true,false})foreach(int which in new[]{0,1}){
                    var v=JsonUtility.FromJson<ForgeSeatView>(File.ReadAllText(Output+"/inputs/order.json"));int calls=0,last=-1;ui.Present(null,1,false,null,null,"");ui.Present(v,acting?v.request.seat:2,acting,i=>{calls++;last=i;},null,"");yield return Frame();foreach(var p in UnityEngine.Object.FindObjectsByType<ForgeBattlefieldCardPointer>(FindObjectsSortMode.None)){p.ResetHover();p.enabled=false;}var panel=Root.Find("AbilityOrder");Check(panel!=null&&panel.gameObject.activeInHierarchy,"Replacement window absent");
                    foreach(var option in v.request.options.Where(o=>o.ability!=null)){
                        var source=option.ability.source;Check(source.id!=151&&source.printingKey==null&&!string.IsNullOrEmpty(source.effectSourcePrintingKey)&&source.effectSourceName=="Embolden"&&source.genericEffectName,"Effect/source identities mixed");var face=panel.GetComponentsInChildren<Transform>().Single(t=>t.name=="AbilityFace"&&t.parent.parent.name=="OrderedAbility_"+option.ability.id);Check(CardImageLibrary.TryLoadPrintingKey(source.effectSourcePrintingKey,out var sprite)&&face.Find("Art").GetComponent<RawImage>().texture==sprite.texture,"Generated source artwork missing");string title=face.Find("Name").GetComponent<Text>().text;Check(title.StartsWith(GamePreferences.CardFaceName("Embolden"))&&!title.Contains("151")&&!title.Contains("188")&&!title.Contains("187"),"Generic effect title/debug ID");var label=face.Find("EffectClip/Effect").GetComponent<Text>();var text=label.GetComponentInChildren<TMPro.TextMeshProUGUI>();Check(label.text.Contains(lang=="zh-CN"?"剩余预防量：":lang=="en-US"?"Shields remain:":"残りの軽減量：")&&label.text.Contains(option.ability.id==4?"1":"3"),"Dynamic prevention amount changed");Check(!label.resizeTextForBestFit&&!text.enableAutoSizing&&text.text==CardSymbolText.Format(label.text),"Rules symbols/font");
                    }
                    var fonts=panel.GetComponentsInChildren<TMPro.TextMeshProUGUI>().Select(t=>t.fontSize).ToArray();ui.ViewBattlefield();yield return Frame();Check(panel.GetComponentInParent<CanvasGroup>().alpha==0,"Window hidden incorrectly");ui.RestoreBattlefieldWindows();yield return Frame();Check(fonts.SequenceEqual(panel.GetComponentsInChildren<TMPro.TextMeshProUGUI>().Select(t=>t.fontSize))&&calls==0,"Return font/submit drift");var target=v.request.options.Where(o=>o.ability!=null).ElementAt(which);int expected=ui.OptionIndex(target.id);var b=panel.GetComponentsInChildren<Button>().Single(b=>b.name=="OrderedAbility_"+target.ability.id);Click(b);Check(acting?calls==1&&last==expected&&!ui.TrySubmitPresentedOption(expected,v.request.requestId):calls==0&&!ui.TrySubmitPresentedOption(expected,v.request.requestId),"Exact native order ID/read-only/duplicate guard");if(lang=="zh-CN"&&acting&&which==0){ScreenCapture.CaptureScreenshot(Output+"/order.png");yield return Frame();}File.AppendAllText(Output+"/steps.log",lang+" acting="+acting+" "+target.id+" PASS\n");
                }
            }
            var unknown=new ForgeCardView{name="Custom effect",effectSourceName="Embolden",effectSourcePrintingKey="test-key",genericEffectName=false};var flags=BindingFlags.Static|BindingFlags.NonPublic;Check((string)typeof(ForgeBattlefieldController).GetMethod("AbilitySourceName",flags).Invoke(null,new object[]{unknown})=="Custom effect","Custom effect name replaced");string rules="Prevent the next damage chosen by a player.\nShields remain: unknown";Check((string)typeof(ForgeBattlefieldController).GetMethod("AbilityEffectText",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(ui,new object[]{unknown,rules})==rules,"Unknown rule replaced");unknown.faceDown=true;var args=new object[]{unknown,null};Check((bool)typeof(ForgeBattlefieldController).GetMethod("TryBattlefieldArt",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(ui,args)&&args[1]!=null&&CardImageLibrary.TryLoadCardBack(out var back)&&args[1]==back,"Face-down art exposed source");
        }finally{ui.Present(null,1,false,null,null,"");ui.enabled=enabled;GamePreferences.SetLanguage(locale);if(module!=null)module.enabled=active;foreach(var n in notices)if(n.n!=null)n.n.enabled=n.enabled;}
    }
}
#endif
